#!/bin/bash
# Generated by ios-builder. Shared Codemagic/Bitrise runner, macOS Bash 3.2 compatible.
set -euo pipefail

ci_dir="${BUILDER_CI_DIR:-$HOME/.ios-builder-ci}"
mkdir -p "$ci_dir"
mode="${1:-build}"
export IOS_PATH="${IOS_PATH:-.}" SCHEME="${SCHEME:-}" CONFIGURATION="${CONFIGURATION:-Debug}"
export USE_SIGNING="${USE_SIGNING:-false}" JDK_VERSION="${JDK_VERSION:-17}"
# From the selected builder.json profile: DISTRIBUTION (canonical: internal
# arrives as ad-hoc) picks the signing set (IOS_*_<SET> secrets) and the
# profile type install_signing expects; BUILD_ENV is a JSON object exported by
# prepare().
export DISTRIBUTION="${DISTRIBUTION:-}" BUILD_ENV="${BUILD_ENV:-}"
# Codemagic sets BUILD_NUMBER itself (its build counter), so the CLI sends
# the CFBundleVersion to stamp as BUILDER_BUILD_NUMBER; empty means none.
export BUILD_NUMBER="${BUILDER_BUILD_NUMBER:-}"

fail() { echo "$*" >&2; exit 1; }

# Exports the profile's env before any dependency install or build, as the
# GitHub workflows do. Values are base64 per entry so newlines and quotes
# survive; names are checked so a value cannot become a second variable.
export_build_env() {
  [ -n "$BUILD_ENV" ] || return 0
  if [ "$(jq -r 'type' <<< "$BUILD_ENV" 2>/dev/null)" != "object" ]; then echo "BUILD_ENV must be a JSON object of variable names to string values" >&2; exit 1; fi
  while IFS=' ' read -r key encoded; do
    name=$(printf '%s' "$key" | base64 --decode)
    if ! [[ "$name" =~ ^[A-Za-z_][A-Za-z0-9_]*$ ]]; then echo "Invalid env name in BUILD_ENV: $name" >&2; exit 1; fi
    export "$name=$(printf '%s' "$encoded" | base64 --decode)"
    echo "env: $name"
  done < <(jq -r 'to_entries[] | "\(.key | @base64) \(.value | tostring | @base64)"' <<< "$BUILD_ENV")
}

snapshot_checkout() {
  case "${SNAPSHOT_REF:-}" in
    refs/ios-builder/jobs/*) ;;
    *) echo "Missing or invalid SNAPSHOT_REF" >&2; exit 1 ;;
  esac
  if ! [[ "${SNAPSHOT_SHA:-}" =~ ^[a-f0-9]{40}$ ]]; then
    echo "Missing or invalid SNAPSHOT_SHA" >&2; exit 1
  fi
  git fetch --no-tags --depth=1 origin "$SNAPSHOT_REF"
  if [ "$(git rev-parse FETCH_HEAD)" != "$SNAPSHOT_SHA" ]; then
    echo "Snapshot SHA mismatch; refusing to build different source" >&2; exit 1
  fi
  git checkout --force --detach "$SNAPSHOT_SHA"
  export BUILDER_WORKSPACE="$(pwd)"
  echo "Building snapshot $SNAPSHOT_SHA"
}

# >>> js toolchain (keep identical across ios-build.yml, ios-share.yml, runner.sh)
# The package manager the project actually uses: the packageManager field
# first, then the lockfile, then npm. Guessing npm is not safe — `npm install`
# in a pnpm or yarn workspace fails with
# 'EUNSUPPORTEDPROTOCOL Unsupported URL Type "workspace:"'.
js_detect_manager() {
  if [ -z "${JS_MANAGER:-}" ]; then
    case "$(jq -r '.packageManager // empty' package.json 2>/dev/null || true)" in
      pnpm|pnpm@*) JS_MANAGER=pnpm ;;
      yarn|yarn@*) JS_MANAGER=yarn ;;
      bun|bun@*) JS_MANAGER=bun ;;
      npm|npm@*) JS_MANAGER=npm ;;
      *)
        if [ -f pnpm-lock.yaml ]; then JS_MANAGER=pnpm
        elif [ -f yarn.lock ]; then JS_MANAGER=yarn
        elif [ -f bun.lock ] || [ -f bun.lockb ]; then JS_MANAGER=bun
        else JS_MANAGER=npm # package-lock.json, or no lockfile at all
        fi
        ;;
    esac
  fi
  case "$JS_MANAGER" in
    pnpm) JS_EXEC='pnpm exec' ;;
    yarn) JS_EXEC=yarn ;;
    bun) JS_EXEC=bunx ;;
    *) JS_EXEC=npx ;;
  esac
  export JS_MANAGER JS_EXEC
  echo "Package manager: $JS_MANAGER"
}

# The Node version the project asks for: .nvmrc or .node-version, else the
# first comparator of engines.node, else 22. A leading "v" or range prefix
# is dropped: nvm, n and setup-node all take "20.11.1" and "24.x" as they are.
js_node_version() {
  js_version=""
  for js_file in .nvmrc .node-version; do
    if [ -f "$js_file" ]; then
      js_version=$(tr -d ' \t\r' < "$js_file" | head -n1)
      break
    fi
  done
  if [ -z "$js_version" ]; then
    js_version=$(jq -r '.engines.node // empty' package.json 2>/dev/null || true)
    js_version=$(printf '%s' "${js_version%%|*}" | awk '{print $1}')
  fi
  js_version=$(printf '%s' "$js_version" | sed -E 's/^(>=|<=|>|<|=|\^|~|v)+//')
  case "$js_version" in
    [0-9]*|lts/*) ;;
    *) js_version=22 ;;
  esac
  printf '%s\n' "$js_version"
}

# Put the manager on PATH first, then install — unless a cache already restored
# node_modules, in which case the manager is still wanted for `expo prebuild`
# and for the React Native build phases that shell out to it.
js_install() {
  js_detect_manager
  case "$JS_MANAGER" in
    pnpm|yarn)
      # corepack installs the version packageManager pins. Node 16.10-24
      # bundle it; Node 25+ and some provider images do not.
      command -v corepack >/dev/null 2>&1 || npm install -g corepack || true
      corepack enable || true
      command -v "$JS_MANAGER" >/dev/null 2>&1 || npm install -g "$JS_MANAGER"
      ;;
    bun)
      if ! command -v bun >/dev/null 2>&1; then
        curl -fsSL https://bun.sh/install | bash
        export BUN_INSTALL="${BUN_INSTALL:-$HOME/.bun}"
        export PATH="$BUN_INSTALL/bin:$PATH"
        # A step's PATH does not survive into the next GitHub Actions step.
        if [ -n "${GITHUB_PATH:-}" ]; then echo "$BUN_INSTALL/bin" >> "$GITHUB_PATH"; fi
      fi
      ;;
  esac
  if [ "${JS_DEPS_CACHED:-}" = "true" ]; then
    echo "node_modules restored from cache; skipping install"
    return 0
  fi
  case "$JS_MANAGER" in
    pnpm)
      if [ -f pnpm-lock.yaml ]; then pnpm install --frozen-lockfile; else pnpm install; fi
      ;;
    yarn)
      if [ -f .yarnrc.yml ]; then yarn install --immutable
      elif [ -f yarn.lock ]; then yarn install --frozen-lockfile
      else yarn install
      fi
      ;;
    bun)
      if [ -f bun.lock ] || [ -f bun.lockb ]; then bun install --frozen-lockfile; else bun install; fi
      ;;
    *)
      if [ -f package-lock.json ]; then npm ci; else npm install; fi
      ;;
  esac
}
# <<< js toolchain

# Codemagic and Bitrise images ship Node already, so a mismatch is worth a log
# line, not a failed build. Switch only when a version manager is right there.
js_use_node_version() {
  wanted_node=$(js_node_version)
  nvm_node="${wanted_node%.x}" # nvm and n want 24, not the setup-node spelling 24.x
  nvm_sh="${NVM_DIR:-$HOME/.nvm}/nvm.sh"
  if [ -s "$nvm_sh" ]; then
    set +u # nvm.sh reads variables it has not set yet
    # shellcheck source=/dev/null
    . "$nvm_sh"
    nvm install "$nvm_node" || true
    set -u
  elif command -v n >/dev/null; then
    n install "$nvm_node" || true
  fi
  echo "Node $(node --version 2>/dev/null || echo unknown); the project asks for $wanted_node"
}

# A managed Expo project keeps no ios/ directory in git; `expo prebuild`
# generates it from app.json / app.config.js. An ejected project already has
# one and must keep it. CI=1 stops prebuild from prompting, which on a runner
# would mean waiting for the job timeout.
expo_prebuild() {
  if [ -n "$(find "$IOS_PATH" -maxdepth 1 \( -name '*.xcodeproj' -o -name '*.xcworkspace' \) -print -quit 2>/dev/null)" ]; then
    echo "$IOS_PATH already holds an Xcode project (ejected Expo); skipping prebuild"
    return 0
  fi
  bundle_id=$(${JS_EXEC:-npx} expo config --type public --json 2>/dev/null | jq -r '.ios.bundleIdentifier // empty' 2>/dev/null || true)
  if [ -z "$bundle_id" ]; then
    for manifest in app.json app.config.json; do
      if [ -f "$manifest" ]; then
        bundle_id=$(jq -r '(.expo.ios.bundleIdentifier // .ios.bundleIdentifier) // empty' "$manifest" 2>/dev/null || true)
        if [ -n "$bundle_id" ]; then break; fi
      fi
    done
  fi
  if [ -z "$bundle_id" ]; then
    echo "This managed Expo project has no ios.bundleIdentifier; set expo.ios.bundleIdentifier in app.json or app.config.js, since 'expo prebuild' cannot run unattended without it" >&2
    exit 1
  fi
  echo "Prebuilding $bundle_id into $IOS_PATH"
  CI=1 ${JS_EXEC:-npx} expo prebuild --platform ios --no-install
  if [ -z "$(find "$IOS_PATH" -maxdepth 1 -name '*.xcodeproj' -print -quit 2>/dev/null)" ]; then
    echo "'expo prebuild' produced no Xcode project in $IOS_PATH; set ios.path in builder.json if it lands elsewhere" >&2
    exit 1
  fi
}

prepare() {
  if [ -f pubspec.yaml ]; then
    project_type=flutter
  elif [ -f package.json ] && grep -q '"expo"' package.json; then
    project_type=expo
  elif [ -f package.json ] && grep -q '"react-native"' package.json; then
    project_type=reactnative
  elif grep -rqlE 'kotlin\("multiplatform"\)|org\.jetbrains\.kotlin\.multiplatform|id\("org.jetbrains.kotlin.multiplatform"\)' --include='*.gradle.kts' --include='*.gradle' --include='libs.versions.toml' . 2>/dev/null; then
    project_type=kmp
  else
    project_type=native
  fi
  echo "Project type: $project_type"
  if ! command -v jq >/dev/null; then brew install jq; fi
  export_build_env

  # Match the GitHub workflows' committed xcconfig-template convention.
  find . -path ./DerivedData -prune -o -type f \
    \( -name '*.xcconfig.template' -o -name '*.xcconfig.example' -o -name '*.xcconfig.sample' \
       -o -name '*.template.xcconfig' -o -name '*.example.xcconfig' -o -name '*.sample.xcconfig' \) -print \
  | while IFS= read -r template; do
      case "$template" in
        *.xcconfig.template|*.xcconfig.example|*.xcconfig.sample) target="${template%.*}" ;;
        *) target="$(dirname "$template")/$(basename "$template" | sed -E 's/\.(template|example|sample)\.xcconfig$/.xcconfig/')" ;;
      esac
      if [ ! -f "$target" ]; then cp "$template" "$target"; echo "Copied template to $target"; fi
    done

  if [ "$project_type" = flutter ]; then
    if [ -n "${FLUTTER_VERSION:-}" ] || ! command -v flutter >/dev/null; then
      flutter_dir="$(mktemp -d "$ci_dir/flutter.XXXXXX")"
      git clone --depth=1 --branch "${FLUTTER_VERSION:-stable}" https://github.com/flutter/flutter.git "$flutter_dir/sdk"
      export PATH="$flutter_dir/sdk/bin:$PATH"
    fi
    flutter pub get
  elif [ "$project_type" = reactnative ] || [ "$project_type" = expo ]; then
    if ! command -v node >/dev/null; then brew install node@22; export PATH="$(brew --prefix node@22)/bin:$PATH"; fi
    js_use_node_version
    js_install
    if [ "$project_type" = expo ]; then expo_prebuild; fi
  elif [ "$project_type" = kmp ]; then
    if ! [[ "$JDK_VERSION" =~ ^[0-9]+$ ]]; then echo "JDK_VERSION must be a major version" >&2; exit 1; fi
    if JAVA_HOME=$(/usr/libexec/java_home -v "$JDK_VERSION" 2>/dev/null); then
      export JAVA_HOME
    else
      brew install "openjdk@$JDK_VERSION"
      export JAVA_HOME="$(brew --prefix "openjdk@$JDK_VERSION")/libexec/openjdk.jdk/Contents/Home"
    fi
    export PATH="$JAVA_HOME/bin:$PATH"
    if [ -f gradlew ]; then chmod +x gradlew; fi
  fi

  cd "$BUILDER_WORKSPACE/$IOS_PATH"
  if [ -z "$(find . -maxdepth 1 -name '*.xcodeproj' -print -quit)" ]; then
    for manifest in project.yml project.yaml; do
      if [ -f "$manifest" ] && grep -qE '^targets:' "$manifest"; then
        if ! command -v xcodegen >/dev/null; then brew install xcodegen; fi
        xcodegen generate --spec "$manifest"
        break
      fi
    done
  fi
  if [ -f Podfile ]; then
    if ! command -v pod >/dev/null; then brew install cocoapods; fi
    pod install
  fi
  cd "$BUILDER_WORKSPACE"
}

select_project() {
  cd "$BUILDER_WORKSPACE/$IOS_PATH"
  workspace=$(find . -maxdepth 1 -name '*.xcworkspace' -print -quit)
  project=$(find . -maxdepth 1 -name '*.xcodeproj' -print -quit)
  if [ -n "$workspace" ]; then target=(-workspace "$workspace"); base=$(basename "$workspace" .xcworkspace)
  elif [ -n "$project" ]; then target=(-project "$project"); base=$(basename "$project" .xcodeproj)
  else echo "No Xcode project/workspace in $IOS_PATH" >&2; exit 1
  fi
  if [ -z "$SCHEME" ]; then
    if [ "$project_type" = flutter ]; then SCHEME=Runner
    else
      schemes=$(xcodebuild "${target[@]}" -list -json | jq -r '(.workspace // .project).schemes[]?')
      SCHEME=$(printf '%s\n' "$schemes" | grep -Fx "$base" || true)
      if [ -z "$SCHEME" ]; then
        while IFS= read -r candidate; do
          case "$candidate" in ''|Pods-*) continue ;; esac
          [ -z "$(find . -maxdepth 4 -path "*/$candidate/Package.swift" -print -quit)" ] || continue
          SCHEME=$candidate; break
        done <<< "$schemes"
      fi
    fi
  fi
  if [ -z "$SCHEME" ]; then echo "No app scheme found; set ios.scheme in builder.json" >&2; exit 1; fi
}

cleanup_signing() {
  if [ -n "${keychain_path:-}" ]; then security delete-keychain "$keychain_path" || true; fi
  if [ -n "${profile_dest:-}" ]; then rm -f "$profile_dest"; fi
  if [ -n "${signing_dir:-}" ]; then rm -rf "$signing_dir"; fi
}

# The export method has to match the profile, or -exportArchive fails and App
# Store Connect rejects the IPA. Xcode 15.3+ also accepts
# debugging/release-testing/app-store-connect, but these legacy names still work
# in Xcode 16 and are the only ones older Xcodes (pinned or self-hosted runners)
# understand, so both templates use them.
detect_export_method() {
  if [ "$(plutil -extract ProvisionsAllDevices raw -o - "$1" 2>/dev/null)" = "true" ]; then
    echo enterprise
  elif plutil -extract ProvisionedDevices xml1 -o /dev/null "$1" >/dev/null 2>&1; then
    if [ "$(plutil -extract Entitlements.get-task-allow raw -o - "$1" 2>/dev/null)" = "true" ]; then
      echo development
    else
      echo ad-hoc
    fi
  else
    echo app-store
  fi
}

# The certificate names that can sign for a profile of this type, the
# current one first. Apple renamed the certificates in 2021; keychains
# still hold iPhone Developer / iPhone Distribution certificates that
# sign exactly the same profiles. Duplicated verbatim in ios-build.yml
# and runner.sh.
signing_identities() {
  case "$1" in
    development) printf '%s\n' "Apple Development" "iPhone Developer" ;;
    ad-hoc|app-store|enterprise) printf '%s\n' "Apple Distribution" "iPhone Distribution" ;;
    *) return 1 ;;
  esac
}

# The identity to archive with: the first of those names the imported
# certificate actually goes by ($2 is security find-identity output).
# Without an explicit CODE_SIGN_IDENTITY the archive keeps the
# project's default, and Xcode refuses to pair a development identity
# with a distribution profile: "No signing certificate iOS Development
# found". Duplicated verbatim in ios-build.yml and runner.sh.
signing_identity() {
  local names name
  names=$(signing_identities "$1") || return 1
  while IFS= read -r name; do
    case "$2" in *"$name: "*) echo "$name"; return 0 ;; esac
  done <<< "$names"
  return 2
}

# The suffix of the IOS_* secrets a distribution is signed with: its
# canonical name upper-cased. No distribution has no set (the legacy
# ios.signing path reads the unsuffixed secrets). Same table in ios-build.yml.
signing_set() {
  case "$1" in
    '') echo '' ;;
    development) echo DEVELOPMENT ;;
    ad-hoc|internal) echo AD_HOC ;;
    store) echo STORE ;;
    enterprise) echo ENTERPRISE ;;
    *) return 1 ;;
  esac
}

# Picks the secrets of the set the build profile's distribution names
# (IOS_CERTIFICATE_<SET> and friends) into IOS_CERTIFICATE,
# IOS_CERTIFICATE_PASSWORD and IOS_PROVISIONING_PROFILE. A set needs all three
# (builder signing setup always writes a password). With no distribution —
# ios.signing without a profile — the unsuffixed secrets are used as they are,
# password optional. SIGNING_SET_USED says which it was. Same function in
# ios-build.yml.
select_signing_set() {
  if [ -z "$SIGNING_SET" ]; then
    if [ -z "${IOS_CERTIFICATE:-}" ] || [ -z "${IOS_PROVISIONING_PROFILE:-}" ]; then
      fail "No signing secrets: ios.signing needs IOS_CERTIFICATE, IOS_CERTIFICATE_PASSWORD and IOS_PROVISIONING_PROFILE; a build profile with a distribution reads its own IOS_*_<SET> secrets instead (builder signing setup --distribution <d> writes them)."
    fi
    IOS_CERTIFICATE_PASSWORD="${IOS_CERTIFICATE_PASSWORD:-}"
    SIGNING_SET_USED=legacy
  else
    local cert="IOS_CERTIFICATE_$SIGNING_SET" pass="IOS_CERTIFICATE_PASSWORD_$SIGNING_SET" prof="IOS_PROVISIONING_PROFILE_$SIGNING_SET"
    local missing="" name
    for name in "$cert" "$pass" "$prof"; do
      [ -n "${!name:-}" ] || missing="${missing:+$missing, }$name"
    done
    [ -z "$missing" ] || fail "Signing set $SIGNING_SET for distribution $DISTRIBUTION is missing $missing. Run builder signing setup --distribution $DISTRIBUTION (builder ios build does it too when an App Store Connect key is configured)."
    IOS_CERTIFICATE="${!cert}"
    IOS_CERTIFICATE_PASSWORD="${!pass}"
    IOS_PROVISIONING_PROFILE="${!prof}"
    SIGNING_SET_USED="$SIGNING_SET"
  fi
  echo "Signing set: $SIGNING_SET_USED"
}

# The profile in the set must be the type the build profile asked for, or the
# export method, and the IPA, would not be what the profile promised. Names
# are compared canonically: the export method calls the store distribution
# app-store, and a tag build may say internal for ad-hoc. The unsuffixed
# secrets (no distribution) are taken as they are.
check_signing_set() {
  [ "$SIGNING_SET_USED" != legacy ] || return 0
  local have="$1" want="$DISTRIBUTION"
  case "$have" in app-store) have=store ;; esac
  case "$want" in internal) want=ad-hoc ;; esac
  if [ "$have" != "$want" ]; then
    fail "IOS_PROVISIONING_PROFILE_$SIGNING_SET holds a $1 provisioning profile, but the build profile asks for distribution $want. Run builder signing setup --distribution $want, or set the profile's distribution to $have."
  fi
}

# Manual signing goes into the app target's build configurations, not on
# the xcodebuild command line: a command-line setting applies to every
# target in the workspace, and a CocoaPods framework target refuses a
# provisioning profile ("FirebaseCore does not support provisioning
# profiles"). Edits the application targets of the .xcodeproj files in the
# current directory (Pods/Pods.xcodeproj is a level down): the only one, or
# with several the ones whose PRODUCT_BUNDLE_IDENTIFIER the profile's app id
# ($1, "*" or "com.example.*" for a wildcard) covers. DEVELOPMENT_TEAM,
# PROVISIONING_PROFILE_NAME and CODE_SIGN_IDENTITY come from the
# environment. The pbxproj is written back as an XML plist, which Xcode
# reads like the OpenStep form. Duplicated verbatim in ios-build.yml and
# runner.sh.
apply_signing_to_app_target() {
  local projects=(*.xcodeproj) out
  [ -d "${projects[0]}" ] || fail "No .xcodeproj in $PWD to apply the signing settings to"
  out=$(python3 - "$1" "${projects[@]}" 2>&1 <<'PY'
import json, os, subprocess, sys
app_id, projects = sys.argv[1], sys.argv[2:]
settings = {'CODE_SIGN_STYLE': 'Manual', 'DEVELOPMENT_TEAM': os.environ['DEVELOPMENT_TEAM'],
            'PROVISIONING_PROFILE_SPECIFIER': os.environ['PROVISIONING_PROFILE_NAME'],
            'CODE_SIGN_IDENTITY': os.environ['CODE_SIGN_IDENTITY']}

def covers(bundle_id):
    if app_id.endswith('*'):
        return bundle_id.startswith(app_id[:-1])
    return bundle_id == app_id

apps, plists = [], {}
for project in projects:
    path = os.path.join(project, 'project.pbxproj')
    plists[project] = json.loads(subprocess.check_output(['plutil', '-convert', 'json', '-o', '-', path]))
    objects = plists[project]['objects']
    for target in objects.values():
        if target.get('isa') != 'PBXNativeTarget' or target.get('productType') != 'com.apple.product-type.application':
            continue
        configs = [objects[c] for c in objects[target['buildConfigurationList']]['buildConfigurations']]
        ids = sorted({c.setdefault('buildSettings', {}).get('PRODUCT_BUNDLE_IDENTIFIER', '') for c in configs})
        apps.append((project, target['name'], configs, ids))
if not apps:
    sys.exit('No application target in %s to apply the signing settings to' % ', '.join(projects))
chosen = apps if len(apps) == 1 else [a for a in apps if any(covers(i) for i in a[3])]
if not chosen:
    found = '; '.join('%s in %s (%s)' % (name, project, ', '.join(i or '?' for i in ids)) for project, name, _, ids in apps)
    sys.exit('No application target has the PRODUCT_BUNDLE_IDENTIFIER the provisioning profile covers (%s): %s' % (app_id, found))
for project, name, configs, _ in chosen:
    for config in configs:
        build = config['buildSettings']
        # A conditional setting (CODE_SIGN_IDENTITY[sdk=iphoneos*]) would win over the plain one.
        for key in [k for k in build if k.split('[')[0] in settings]:
            del build[key]
        build.update(settings)
    print('Signing settings applied to target %s in %s: %s' % (name, project, ', '.join(c['name'] for c in configs)))
for project in sorted({a[0] for a in chosen}):
    subprocess.run(['plutil', '-convert', 'xml1', '-o', os.path.join(project, 'project.pbxproj'), '-'],
                   input=json.dumps(plists[project]).encode(), check=True)
PY
  ) || fail "$out"
  echo "$out"
}

install_signing() {
  SIGNING_SET=$(signing_set "$DISTRIBUTION") || fail "DISTRIBUTION \"$DISTRIBUTION\" must be development, ad-hoc (or internal), store or enterprise"
  select_signing_set
  signing_dir=$(mktemp -d "$ci_dir/signing.XXXXXX")
  trap cleanup_signing EXIT
  # Read the profile first: its type is checked against the build profile
  # before any keychain exists or the certificate is imported.
  printf '%s' "$IOS_PROVISIONING_PROFILE" | base64 --decode > "$signing_dir/profile.mobileprovision"
  security cms -D -i "$signing_dir/profile.mobileprovision" > "$signing_dir/profile.plist"
  profile_uuid=$(plutil -extract UUID raw -o - "$signing_dir/profile.plist")
  export DEVELOPMENT_TEAM="$(plutil -extract TeamIdentifier.0 raw -o - "$signing_dir/profile.plist")"
  export PROVISIONING_PROFILE_NAME="$(plutil -extract Name raw -o - "$signing_dir/profile.plist")"
  # The app id the profile covers, without the team prefix: the target to
  # sign is the one whose bundle id it matches.
  app_id=$(plutil -extract Entitlements.application-identifier raw -o - "$signing_dir/profile.plist")
  export PROFILE_BUNDLE_ID="${app_id#"$DEVELOPMENT_TEAM".}"
  export EXPORT_METHOD="$(detect_export_method "$signing_dir/profile.plist")"
  check_signing_set "$EXPORT_METHOD"
  echo "Signing with '$PROVISIONING_PROFILE_NAME' (team $DEVELOPMENT_TEAM, app id $PROFILE_BUNDLE_ID, set $SIGNING_SET_USED), export method $EXPORT_METHOD"
  # A Debug archive carries get-task-allow=true, which no distribution profile
  # grants: the export fails, or an IPA that App Store Connect rejects comes
  # out. Say so now instead of after the whole build.
  if [ "$EXPORT_METHOD" != development ] && [ "$CONFIGURATION" = Debug ]; then
    echo "The provisioning profile is an $EXPORT_METHOD profile, but the build configuration is Debug. A Debug build is signed with get-task-allow, which distribution profiles do not allow and App Store Connect rejects. Drop the profile's \"configuration\" (a distribution build defaults to Release) or set \"configuration\": \"Release\", or build with a development profile." >&2
    exit 1
  fi
  keychain_path="$signing_dir/signing.keychain-db"
  keychain_password=$(openssl rand -base64 32)
  security create-keychain -p "$keychain_password" "$keychain_path"
  security set-keychain-settings -lut 7200 "$keychain_path"
  security unlock-keychain -p "$keychain_password" "$keychain_path"
  printf '%s' "$IOS_CERTIFICATE" | base64 --decode > "$signing_dir/certificate.p12"
  security import "$signing_dir/certificate.p12" -P "$IOS_CERTIFICATE_PASSWORD" -A -t cert -f pkcs12 -k "$keychain_path"
  security set-key-partition-list -S apple-tool:,apple: -k "$keychain_password" "$keychain_path"
  security list-keychains -d user -s "$keychain_path" "$HOME/Library/Keychains/login.keychain-db"
  # The certificate has to be the kind the profile asks for, under whichever of
  # its names it carries. Say so here instead of letting xcodebuild discover it
  # after the whole archive.
  identities=$(security find-identity -v -p codesigning "$keychain_path")
  echo "$identities"
  CODE_SIGN_IDENTITY=$(signing_identity "$EXPORT_METHOD" "$identities") ||
    fail "IOS_CERTIFICATE${SIGNING_SET:+_$SIGNING_SET} holds no $(signing_identities "$EXPORT_METHOD" | paste -sd '/' -) certificate, which an $EXPORT_METHOD profile must be signed with. Run builder signing setup --distribution ${DISTRIBUTION:-<distribution>} to issue the right one."
  export CODE_SIGN_IDENTITY
  echo "Signing identity: $CODE_SIGN_IDENTITY"
  mkdir -p "$HOME/Library/MobileDevice/Provisioning Profiles"
  profile_dest="$HOME/Library/MobileDevice/Provisioning Profiles/$profile_uuid.mobileprovision"
  cp "$signing_dir/profile.mobileprovision" "$profile_dest"
}

# BUILD_NUMBER is "N" or "X.Y.Z+N" (pubspec convention); sets build_number,
# build_name and version_settings for xcodebuild. Given a target and scheme
# it also rewrites an Info.plist that hardcodes CFBundleVersion, which
# CURRENT_PROJECT_VERSION never reaches; identical in ios-build.yml and runner.sh.
apply_build_number() {
  build_number="" build_name="" version_settings=""
  [ -n "${BUILD_NUMBER:-}" ] || return 0
  if ! [[ "$BUILD_NUMBER" =~ ^([0-9]+(\.[0-9]+)*\+)?[0-9]+(\.[0-9]+)*$ ]]; then
    echo "BUILD_NUMBER must be N or X.Y.Z+N, got '$BUILD_NUMBER'" >&2
    return 1
  fi
  build_number="${BUILD_NUMBER##*+}"
  case "$BUILD_NUMBER" in *+*) build_name="${BUILD_NUMBER%+*}" ;; esac
  version_settings="CURRENT_PROJECT_VERSION=$build_number${build_name:+ MARKETING_VERSION=$build_name}"
  echo "Build number: $build_number${build_name:+ (version $build_name)}"
  [ $# -gt 0 ] || return 0
  plist=$(xcodebuild "$@" -showBuildSettings -json 2>/dev/null \
    | jq -r 'map(.buildSettings)
             | map(select(.PRODUCT_TYPE == "com.apple.product-type.application" and .INFOPLIST_FILE != null and .INFOPLIST_FILE != ""))
             | map(.SRCROOT + "/" + .INFOPLIST_FILE) | first // empty' || true)
  if [ -z "$plist" ] || [ ! -f "$plist" ]; then
    echo "No Info.plist file in the app target; CFBundleVersion comes from CURRENT_PROJECT_VERSION"
    return 0
  fi
  current=$(plutil -extract CFBundleVersion raw -o - "$plist" 2>/dev/null || true)
  case "$current" in
    '$(CURRENT_PROJECT_VERSION)'|'${CURRENT_PROJECT_VERSION}'|'$(FLUTTER_BUILD_NUMBER)'|'${FLUTTER_BUILD_NUMBER}')
      echo "$plist reads CFBundleVersion from $current" ;;
    *)
      echo "$plist hardcodes CFBundleVersion '$current'; setting $build_number in the plist"
      plutil -replace CFBundleVersion -string "$build_number" "$plist" ;;
  esac
  [ -n "$build_name" ] || return 0
  current=$(plutil -extract CFBundleShortVersionString raw -o - "$plist" 2>/dev/null || true)
  case "$current" in
    '$(MARKETING_VERSION)'|'${MARKETING_VERSION}'|'$(FLUTTER_BUILD_NAME)'|'${FLUTTER_BUILD_NAME}') ;;
    *)
      echo "$plist hardcodes CFBundleShortVersionString '$current'; setting $build_name in the plist"
      plutil -replace CFBundleShortVersionString -string "$build_name" "$plist" ;;
  esac
}

build_ipa() {
  # Before the compile, so a profile/configuration mismatch fails without
  # waiting for the archive.
  if [ "$USE_SIGNING" = true ]; then install_signing; fi
  apply_build_number
  if [ "$project_type" = flutter ]; then
    cd "$BUILDER_WORKSPACE"
    flutter_flags=(--no-codesign)
    if [ -n "$build_number" ]; then flutter_flags+=("--build-number=$build_number"); fi
    if [ -n "$build_name" ]; then flutter_flags+=("--build-name=$build_name"); fi
    case "$CONFIGURATION" in Debug) flutter build ios --debug "${flutter_flags[@]}" ;; *) flutter build ios --release "${flutter_flags[@]}" ;; esac
  fi
  select_project
  # Flutter wrote the build number into Generated.xcconfig; for it this only
  # catches a Runner Info.plist that hardcodes CFBundleVersion.
  apply_build_number "${target[@]}" -scheme "$SCHEME"
  # version_settings is unquoted on purpose: validated above, it holds zero
  # to two KEY=VALUE words.
  args=("${target[@]}" -scheme "$SCHEME" -configuration "$CONFIGURATION" -destination 'generic/platform=iOS'
    -derivedDataPath "$BUILDER_WORKSPACE/DerivedData" COMPILER_INDEX_STORE_ENABLE=NO $version_settings)
  mkdir -p "$BUILDER_WORKSPACE/build"
  if [ "$USE_SIGNING" = true ]; then
    # After pod install / expo prebuild / flutter build ios, so the project
    # the archive reads exists; select_project left us in the iOS directory.
    apply_signing_to_app_target "$PROFILE_BUNDLE_ID"
    xcodebuild "${args[@]}" -archivePath "$BUILDER_WORKSPACE/build/App.xcarchive" archive
    export APP_BUNDLE_ID="$(plutil -extract ApplicationProperties.CFBundleIdentifier raw -o - "$BUILDER_WORKSPACE/build/App.xcarchive/Info.plist")"
    python3 - "$signing_dir/ExportOptions.plist" <<'PY'
import os, plistlib, sys
options = {'method': os.environ['EXPORT_METHOD'], 'signingStyle': 'manual',
           'teamID': os.environ['DEVELOPMENT_TEAM'],
           'provisioningProfiles': {os.environ['APP_BUNDLE_ID']: os.environ['PROVISIONING_PROFILE_NAME']}}
# Distribution exports keep the version numbers the archive was built with;
# Xcode would otherwise renumber the build on export.
if options['method'] != 'development':
    options['manageAppVersionAndBuildNumber'] = False
with open(sys.argv[1], 'wb') as out:
    plistlib.dump(options, out)
PY
    xcodebuild -exportArchive -archivePath "$BUILDER_WORKSPACE/build/App.xcarchive" \
      -exportOptionsPlist "$signing_dir/ExportOptions.plist" -exportPath "$signing_dir/export"
    ipa=$(find "$signing_dir/export" -maxdepth 1 -name '*.ipa' -print -quit)
    test -n "$ipa"
    cp "$ipa" "$BUILDER_WORKSPACE/build/$BUILD_ID.ipa"
  else
    if [ "$project_type" = flutter ]; then
      app_path=$(find "$BUILDER_WORKSPACE/build/ios/iphoneos" -maxdepth 1 -name '*.app' -print -quit)
    else
      xcodebuild "${args[@]}" CODE_SIGNING_ALLOWED=NO build
      app_path=$(xcodebuild "${args[@]}" -showBuildSettings -json | jq -r 'map(.buildSettings) | map(select(.PRODUCT_TYPE == "com.apple.product-type.application" and (.TARGET_BUILD_DIR | contains("-iphoneos")))) | map(.TARGET_BUILD_DIR + "/" + .FULL_PRODUCT_NAME) | first // empty')
    fi
    test -d "$app_path"
    payload_dir=$(mktemp -d "$ci_dir/payload.XXXXXX")
    mkdir -p "$payload_dir/Payload"
    cp -R "$app_path" "$payload_dir/Payload/"
    (cd "$payload_dir"; zip -rq "$BUILDER_WORKSPACE/build/$BUILD_ID.ipa" Payload)
    rm -rf "$payload_dir"
  fi
  echo "Created build/$BUILD_ID.ipa"
}

build_simulator() {
  : "${MOBAI_API_KEY:?Set MOBAI_API_KEY on this provider to share a simulator}"
  if ! command -v mobai-ci >/dev/null; then
    curl -fsSL https://raw.githubusercontent.com/MobAI-App/mobai-ci/v1/install.sh -o "$ci_dir/install-mobai.sh"
    MOBAI_CI_BIN_DIR="$ci_dir/bin" sh "$ci_dir/install-mobai.sh"
    export PATH="$ci_dir/bin:$PATH"
  fi
  sim_udid=$(mobai-ci sim boot --cache "$ci_dir/sim-cache" --device-type 'iPhone 16 Pro' --runtime latest | tail -1)
  test -n "$sim_udid"
  if [ "$project_type" = flutter ]; then
    cd "$BUILDER_WORKSPACE"
    flutter build ios --simulator --debug
    app_path=$(find "$BUILDER_WORKSPACE/build/ios/iphonesimulator" -maxdepth 1 -name '*.app' -print -quit)
  else
    select_project
    args=("${target[@]}" -scheme "$SCHEME" -configuration Debug -destination "id=$sim_udid"
      -derivedDataPath "$BUILDER_WORKSPACE/DerivedData" COMPILER_INDEX_STORE_ENABLE=NO CODE_SIGNING_ALLOWED=NO)
    xcodebuild "${args[@]}" build
    app_path=$(xcodebuild "${args[@]}" -showBuildSettings -json | jq -r 'map(.buildSettings) | map(select(.PRODUCT_TYPE == "com.apple.product-type.application" and (.TARGET_BUILD_DIR | contains("-iphonesimulator")))) | map(.TARGET_BUILD_DIR + "/" + .FULL_PRODUCT_NAME) | first // empty')
  fi
  test -d "$app_path"
  printf '%s\n' "$app_path" > "$ci_dir/app-path"
  printf '%s\n' "$sim_udid" > "$ci_dir/sim-udid"
}

case "$mode" in
  checkout) snapshot_checkout ;;
  build|simulator)
    if ! [[ "${BUILD_ID:-}" =~ ^[a-f0-9]{8}$ ]]; then echo "Invalid BUILD_ID" >&2; exit 1; fi
    snapshot_checkout
    prepare
    if [ "$mode" = build ]; then build_ipa; else build_simulator; fi
    ;;
  share)
    export PATH="$ci_dir/bin:$PATH"
    exec mobai-ci share --device "$(cat "$ci_dir/sim-udid")" --app "$(cat "$ci_dir/app-path")" \
      --duration "${DURATION:-30m}" --label "${BUILDER_REPOSITORY:-Builder} · $BUILD_ID" \
      --wait-device 4m --startup-timeout 5m
    ;;
  *) echo "Unknown runner mode: $mode" >&2; exit 1 ;;
esac
